    'settings':'<path d="M12 2v2m0 16v2M4.93 4.93l1.41 1.41m11.32 11.32 1.41 1.41M2 12h2m16 0h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="2"/>',
    'plus':'<path d="M12 5v14M5 12h14"/>',
