    if(action==='toggle-bill'){const schedules=billSchedules().map(b=>b.id===id?{...b,paused:!b.paused}:b);mutate([{kind:'settings',record:{...data.settings,billSchedules:schedules}}]);toast('Reminder updated.');return;}
