    if(action==='delete-bill'){const b=billSchedules().find(x=>x.id===id);if(!b)return;if(!confirm('Delete '+b.name+' from your reminders? Previous payment transactions will remain in your spending history.'))return;const schedules=billSchedules().filter(x=>x.id!==id),map={...billSkips()};delete map[id];mutate([{kind:'settings',record:{...data.settings,billSchedules:schedules,billSkippedOccurrences:map}}]);toast('Reminder deleted. Historical expenses unchanged.');return;}
    if(action==='edit-transaction'){openModal('transaction',id);return;}
    if(action==='edit-account'){openModal('account',id);return;}
    if(action==='edit-investment'){openModal('investment',id);return;}
